/* file : MenuMapper.xml, id : getBreadcrumb */
SELECT A.MENU_CD
     , A.MENU_NM
     , (SELECT MENU_NM
          FROM TB_MENU B
         WHERE B.MENU_CD = A.UP_MENU_CD
       ) AS PARENT_MENU_NM
  FROM TB_MENU A
 WHERE A.MENU_CD = #{menuCd}
   AND A.DEL_YN  = 'N'

/* file : MenuMapper.xml, id : getMenuList */ WITH RECURSIVE CTE AS ( SELECT MENU_CD , MENU_NM , UP_MENU_CD , MENU_URL , 1 AS LEVEL , ORDBY , DATE_FORMAT(REG_DT, '%Y-%m-%d') AS REG_DT FROM TB_MENU WHERE UP_MENU_CD = 'TOP' AND DEL_YN = 'N' UNION ALL SELECT M.MENU_CD , M.MENU_NM , M.UP_MENU_CD , M.MENU_URL , 1 + CTE.LEVEL AS LEVEL , M.ORDBY , DATE_FORMAT(M.REG_DT, '%Y-%m-%d') AS REG_DT FROM TB_MENU M INNER JOIN CTE ON M.UP_MENU_CD = CTE.MENU_CD WHERE M.DEL_YN = 'N' ) SELECT MENU_CD , MENU_NM , UP_MENU_CD , MENU_URL , LEVEL , ORDBY , REG_DT FROM CTE WHERE 1 = 1
AND ${field} LIKE CONCAT('%', #{keyword}, '%')
ORDER BY MENU_CD /*||ORDER BY MENU_CD||*/

mapper.update:
/* file : MenuMapper.xml, id : deleteAuthMenu */
UPDATE TB_MENU_AUTH
   SET DEL_YN     = 'Y'
     , DEL_USER_SEQ = #{loginUserSeq}
     , DEL_DT     = CURRENT_TIMESTAMP
     , DEL_IP     = #{loginUserIp}
 WHERE AUTH_CD         = #{authCd}

mapper.insert:
/* file : MenuMapper.xml, id : saveMenu */
INSERT
  INTO TB_MENU (
              MENU_CD
            , MENU_NM
            , UP_MENU_CD
            , MENU_URL
            , MENU_ICON
            , ORDBY
            , REG_USER_SEQ
            , REG_IP)
       VALUES (
              UPPER( #{menuCd} )
            , #{menuNm}
            , #{upMenuCd}
            , #{menuUrl}
            , #{menuIcon}
            , #{ordby}
            , #{loginUserSeq}
            , #{loginUserIp})
    ON DUPLICATE KEY UPDATE MENU_NM = #{menuNm}
     , UP_MENU_CD               = #{upMenuCd}
     , MENU_URL                      = #{menuUrl}
     , MENU_ICON                      = #{menuIcon}
     , ORDBY                          = #{ordby}
     , DEL_YN                       = 'N'
     , MDFCN_USER_SEQ                   = #{loginUserSeq}
     , MDFCN_DT                       = CURRENT_TIMESTAMP
     , MDFCN_IP                         = #{loginUserIp}

