/* file : MenuMapper.xml, id : deleteMenu */
  UPDATE TB_MENU
     SET DEL_YN     = 'Y'
       , DEL_USER_SEQ = #{loginUserSeq}
       , DEL_DT     = CURRENT_TIMESTAMP
       , DEL_IP = #{loginUserIp}
   WHERE MENU_CD    = #{menuCd}

/* file : MenuMapper.xml, id : deleteMenuParent */
  UPDATE TB_MENU
     SET DEL_YN         = 'Y'
       , DEL_USER_SEQ     = #{loginUserSeq}
       , DEL_DT         = CURRENT_TIMESTAMP
       , DEL_IP = #{loginUserIp}
   WHERE UP_MENU_CD = #{menuCd}

mapper.select:
/* file : MenuMapper.xml, id : getMenu */
SELECT A.*
  FROM TB_MENU A
 WHERE A.MENU_CD = #{menuCd}
   AND A.DEL_YN  = 'N'

SELECT parent.*
FROM TB_MENU AS child
		 JOIN TB_MENU AS parent ON child.UP_MENU_CD = parent.MENU_CD
WHERE child.MENU_CD = #{menuCd}
  AND parent.UP_MENU_CD != 'TOP';
